+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+/**
+ * A contact form, the messages sent through it, and a bit of care for the
+ * person filling it in: nothing is lost by a mistyped e-mail address or by
+ * navigating away by accident.
+ */
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MESSAGE_MAX_LENGTH = 500;
+
+    static final String NAME_REQUIRED = "Name is required";
+    static final String EMAIL_INVALID = "Enter a valid e-mail address";
+    static final String CONTACT_REQUIRED = "Give an e-mail address or a phone number";
+    static final String MESSAGE_REQUIRED = "Message is required";
+    static final String MESSAGE_TOO_LONG = "Message must be at most " + MESSAGE_MAX_LENGTH + " characters";
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final MessageStore store = MessageStore.current();
+
+    private Dialog leaveDialog;
+
+    public ContactView() {
+        setSizeFull();
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        add(createForm());
+
+        add(new H2("Sent messages"));
+        add(createGrid());
+
+        refreshGrid();
+    }
+
+    private Component createForm() {
+        name.setId("name");
+        email.setId("email");
+        phone.setId("phone");
+        message.setId("message");
+        send.setId("send");
+
+        // The form is validated when Send is pressed, and only then: the field
+        // components must not mark themselves invalid on their own.
+        for (var field : fields()) {
+            field.setManualValidation(true);
+            // Report every keystroke, so that Send becomes enabled again and
+            // unsaved input is noticed even before the field loses focus.
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(event -> send.setEnabled(true));
+        }
+
+        message.setHeight("8em");
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("30em", 2));
+        form.setColspan(message, 2);
+        form.setMaxWidth("40em");
+
+        return new VerticalLayout(form, new HorizontalLayout(send));
+    }
+
+    private Component createGrid() {
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.setId("messages");
+        grid.setAllRowsVisible(true);
+        return grid;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(store.messages());
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+
+        store.add(new ContactMessage(value(name).trim(), value(email).trim(), value(phone).trim(),
+                value(message).trim()));
+        refreshGrid();
+
+        Notification.show("Message sent");
+
+        // Clearing first, then disabling: clearing fires value changes, and
+        // those enable Send again.
+        fields().forEach(HasValue::clear);
+        clearErrors();
+        send.setEnabled(false);
+    }
+
+    /**
+     * Marks every field that fails a rule, and tells whether the form as a
+     * whole may be sent.
+     */
+    private boolean validate() {
+        clearErrors();
+
+        boolean valid = true;
+
+        if (value(name).isBlank()) {
+            invalid(name, NAME_REQUIRED);
+            valid = false;
+        }
+
+        String emailValue = value(email).trim();
+        String phoneValue = value(phone).trim();
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            invalid(email, EMAIL_INVALID);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalid(email, CONTACT_REQUIRED);
+            valid = false;
+        }
+
+        String messageValue = value(message);
+        if (messageValue.isBlank()) {
+            invalid(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (messageValue.length() > MESSAGE_MAX_LENGTH) {
+            invalid(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void invalid(TextFieldBase<?, String> field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (var field : fields()) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        askBeforeLeaving(action);
+    }
+
+    private void askBeforeLeaving(BeforeLeaveEvent.ContinueNavigationAction action) {
+        if (leaveDialog != null) {
+            leaveDialog.close();
+        }
+
+        Dialog dialog = new Dialog();
+        leaveDialog = dialog;
+        dialog.setHeaderTitle("Leave without sending?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            action.cancel();
+        });
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR, ButtonVariant.LUMO_TERTIARY);
+
+        dialog.add(new VerticalLayout(new Paragraph("Your message has not been sent yet."),
+                new HorizontalLayout(keepEditing, discard)));
+        dialog.open();
+    }
+
+    /**
+     * Whether any of the four fields has something in it.
+     */
+    private boolean hasUnsentInput() {
+        return fields().stream().anyMatch(field -> !value(field).isEmpty());
+    }
+
+    private List<TextFieldBase<?, String>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private static String value(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value;
+    }
+}
