+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return find(Grid.class).single();
+    }
+
+    private void fillIn(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(phone()).setValue(phoneValue);
+        test(message()).setValue(messageValue);
+    }
+
+    @Test
+    void contactView_hasHeadingFormAndEnabledSendButton() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(test(send()).isUsable(), "Send should be enabled on an untouched form");
+        assertTrue(find(RouterLink.class).withText("About").exists());
+    }
+
+    @Test
+    void aboutLink_navigatesToAboutView() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyForm_reportsRequiredFields() {
+        navigate(ContactView.class);
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertEquals(0, test(grid()).size());
+        assertFalse(find(Notification.class).exists(), "Nothing should have been sent");
+    }
+
+    @Test
+    void invalidEmail_isReported() {
+        navigate(ContactView.class);
+        fillIn("Ada", "not-an-email", "", "Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+        assertEquals("Ada", name().getValue(), "Input must be kept");
+    }
+
+    @Test
+    void invalidEmailWithPhone_isStillReported() {
+        navigate(ContactView.class);
+        fillIn("Ada", "nope@", "+358 40 123", "Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void maximumLengthMessage_isSent() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void phoneOnly_isEnough() {
+        navigate(ContactView.class);
+        fillIn("Ada", "", "+358 40 123", "Call me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_isSentAndClearsTheForm() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+
+        test(send()).click();
+
+        assertTrue(test(find(Notification.class).single()).getText().contains("Message sent"));
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled(), "Send is disabled right after sending");
+
+        test(name()).setValue("Grace");
+        assertTrue(send().isEnabled(), "Editing enables Send again");
+    }
+
+    @Test
+    void newestMessage_isFirst() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "First");
+        test(send()).click();
+        fillIn("Grace", "grace@example.com", "", "Second");
+        test(send()).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Grace", test(grid()).getCellText(0, 0));
+        assertEquals("Ada", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void enterKey_sendsTheMessage() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Sent with Enter", test(grid()).getCellText(0, 1));
+    }
+
+    @Test
+    void sentMessages_surviveLeavingTheView() {
+        navigate(ContactView.class);
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        navigate(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertFalse(find(Dialog.class).exists(), "No dialog for an empty form");
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void filledForm_asksBeforeLeaving_keepEditing() {
+        navigate(ContactView.class);
+        fillIn("Ada", "", "", "Half written");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(find(Dialog.class).exists(), "A dialog should ask what to do");
+        Button keepEditing = find(Button.class).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertFalse(find(Dialog.class).exists());
